"""
Anthropometric Measurement Exception Classes

Custom exceptions for handling errors in measurement extraction and validation.
"""

from typing import Optional, Dict, Any


class MeasurementExtractionError(Exception):
    """Base exception for measurement extraction errors"""

    def __init__(self, message: str, details: Optional[Dict[str, Any]] = None):
        super().__init__(message)
        self.details = details or {}


class ScaleCalibrationError(MeasurementExtractionError):
    """Exception raised when scale calibration fails"""
    pass


class ValidationError(MeasurementExtractionError):
    """Exception raised when measurement validation fails"""
    pass


class InsufficientDataError(MeasurementExtractionError):
    """Exception raised when insufficient data is available for measurement"""
    pass

