    cv::Point textOrg(topLeft.x + (barWidth - textSize.width) / 2, 
                    topLeft.y + (barHeight + textSize.height) / 2);
    cv::putText(img, text, textOrg, fontFace, fontScale, cv::Scalar(255, 255, 255), thickness);
